-- STEP 10: SQL safety stock and purchase recommendation; never calculate in UI.
alter table core.policy_config add column if not exists z_value numeric;
create table if not exists core.service_level_policy(item_grade text primary key,service_level numeric not null,z_value numeric not null,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create or replace view analytics.v_safety_stock with(security_invoker=true) as with f as(select distinct on(item_id) item_id,run_id,model_version,predicted_qty,sigma from analytics.v_forecast_result order by item_id,period), p as(select distinct on(item_id) item_id,item_grade,moq,pack_size from core.item_policy order by item_id), lt as(select * from analytics.v_effective_lead_time), err as(select item_id,stddev_samp(rmse) sigma_d from analytics.v_model_performance where calculation_status='SUCCESS' group by item_id) select f.item_id,p.item_grade,f.predicted_qty,err.sigma_d,lt.effective_lead_time_days,sl.z_value,case when f.predicted_qty is null then null when err.sigma_d is null then null when lt.effective_lead_time_days is null then null when sl.z_value is null then null else sl.z_value*sqrt(lt.effective_lead_time_days*power(err.sigma_d,2)) end safety_stock,case when f.predicted_qty is null then 'NO_FORECAST' when err.sigma_d is null then 'INSUFFICIENT_FORECAST_ERROR' when lt.effective_lead_time_days is null then 'NO_LEADTIME' when sl.z_value is null then 'NO_SERVICE_LEVEL' end reason_code,f.run_id,f.model_version from f left join p using(item_id) left join lt using(item_id) left join err using(item_id) left join core.service_level_policy sl on sl.item_grade=p.item_grade;
create or replace view analytics.v_purchase_recommendation with(security_invoker=true) as with s as(select * from analytics.v_safety_stock), i as(select item_id,max(beginning_inventory) inventory,max(receipts) receipts from analytics.v_inventory_projection group by item_id), o as(select item_id,sum(confirmed_sales) confirmed_order_qty from analytics.v_inventory_projection group by item_id), p as(select distinct on(item_id) item_id,item_grade,moq,pack_size from core.item_policy order by item_id), r as(select * from analytics.v_stockout_risk) select s.item_id,null::text item_name,p.item_grade,s.predicted_qty forecast_qty,o.confirmed_order_qty,greatest(s.predicted_qty,o.confirmed_order_qty) demand_basis_qty,i.inventory available_inventory,i.receipts scheduled_receipt,s.safety_stock,r.stockout_period stockout_date,s.effective_lead_time_days effective_leadtime,(select safety_buffer_days from core.policy_config where policy_id='DEFAULT') safety_buffer_days,case when s.reason_code is not null or i.inventory is null then null else greatest(greatest(s.predicted_qty,o.confirmed_order_qty)+s.safety_stock-i.inventory-i.receipts,0) end required_qty,p.moq,p.pack_size,case when s.reason_code is not null or i.inventory is null or p.moq is null or p.pack_size is null then null when greatest(s.predicted_qty,o.confirmed_order_qty)+s.safety_stock-i.inventory-i.receipts<=0 then 0 else ceil(greatest(greatest(s.predicted_qty,o.confirmed_order_qty)+s.safety_stock-i.inventory-i.receipts,p.moq)/p.pack_size)*p.pack_size end recommended_qty,case when r.stockout_period is null or s.effective_lead_time_days is null then null else r.stockout_period-s.effective_lead_time_days::int-(select safety_buffer_days from core.policy_config where policy_id='DEFAULT')::int end recommended_order_date,r.risk_status,case when s.reason_code is not null then 'CALCULATION_UNAVAILABLE' when i.inventory is null then 'CALCULATION_UNAVAILABLE' else 'SUCCESS' end calculation_status,coalesce(s.reason_code,case when i.inventory is null then 'NO_INVENTORY_DATA' when p.moq is null or p.pack_size is null then 'NO_ITEM_POLICY' end) reason_code,s.run_id forecast_run_id,s.model_version,jsonb_build_object('forecast',s.predicted_qty,'confirmed_order',o.confirmed_order_qty,'safety_stock',s.safety_stock,'inventory',i.inventory,'open_po',i.receipts,'moq',p.moq,'pack_size',p.pack_size) calculation_trace from s left join i using(item_id) left join o using(item_id) left join p using(item_id) left join r using(item_id);
grant select on analytics.v_safety_stock,analytics.v_purchase_recommendation to authenticated;
